    ("inciting_incident", "একটি গোপন ভূগর্ভস্থ কক্ষে প্রবেশ করে আমির তার বাবার লুকিয়ে রাখা পুরনো রিভলভারটি খুঁজে পায় এবং পরম যত্নে তা পরীক্ষা করে। সেখানে রহিমের মাধ্যমে আন্ডারওয়ার্ল্ডের বিছানো ফাঁদের সব নথি পরিষ্কার হয়। বাবার সেই অস্ত্রটি হাতে তুলে নেওয়ার সাথে সাথে আমিরের মন থেকে সমস্ত দ্বিধা ও ভয় চিরতরে মুছে গিয়ে সে এক দুর্ধর্ষ যোদ্ধায় পরিণত হয়।"),

    # Act 4: Logistics & Airport Stakes (17-24)
    ("investigation", "গোটা দক্ষিণ ভারতের অপরাধ জগতে তীব্র চাঞ্চল্য ছড়িয়ে পড়ে যখন খবর আসে যে আমির ওল্ড সুক বাজারে সরাসরি ইরানি চোরাকারবারীদের কাছ থেকে বিশাল স্বর্ণের চালান কিনে নিয়েছে। প্রতিপক্ষ সিন্ডিকেট হতভম্ব হয়ে পড়ে—কীভাবে কোনো মধ্যস্থতাকারী ছাড়াই এক অকুতোভয় তরুণ একাই আন্তর্জাতিক বাণিজ্যের মূল সাপ্লাই লাইন নিজের নিয়ন্ত্রণে ছিনিয়ে নিতে সাহস পেল!"),
    ("investigation", "রাতের অন্ধকারের বুক চিরে উত্তাল জলপথ ও দুর্গম পাহাড়ি ট্রানজিট রুট দিয়ে সেই কোটি কোটি টাকার স্বর্ণের চালান অত্যন্ত নিরাপদে সরিয়ে নেওয়ার রুদ্ধশ্বাস অভিযান শুরু হয়। শত্রুপক্ষের পেতে রাখা পাহারা ও কাস্টমসের চোখ ফাঁকি দিয়ে আমির তার অসাধারণ দূরদর্শিতা দিয়ে নিজের জীবনের প্রথম বড় চালটি শতভাগ সফলভাবে সম্পন্ন করে।"),
    ("investigation", "এদিকে কাস্টমস গোয়েন্দা কর্মকর্তা সুদর্শন একটি অত্যন্ত গোপনীয় ও জরুরি ফোন বার্তা পায়। তার বিশ্বস্ত তথ্যদাতা তাকে সতর্ক করে দেয় যে দুবাই থেকে কোয়েম্বাটুরগামী একটি আন্তর্জাতিক ফ্লাইটে এক সন্দেহভাজন স্বর্ণের ক্যারিয়ার অবতরণ করতে চলেছে। এই গোপন সংবাদের ভিত্তিতে বিমানবন্দরে কাস্টমস ও কেন্দ্রীয় গোয়েন্দাদের সমন্বয়ে দ্রুত এক নিশ্ছিদ্র নজরদারির ফাঁদ তৈরি করা হয়।"),
    ("investigation", "বিমানবন্দরের প্রধান সিকিউরিটি কন্ট্রোল রুমে বসে থাকা অফিসাররা সিসিটিভি স্ক্রিনে সন্দেহভাজন যাত্রীকে নিখুঁতভাবে চিহ্নিত করে ফেলে। মনিটরের পর্দায় অফিসাররা তার প্রতিটি গতিবিধি ও ব্যাগের ওপর সার্বক্ষণিক কড়া নজর রাখতে থাকে। টার্মিনালের নির্দিষ্ট গেট দিয়ে লোকটি বের হওয়ার মুহূর্তে তাকে চারপাশ থেকে নিঃশব্দে ঘিরে ফেলার নির্দেশ জারি করা হয়।"),
    ("investigation", "আটক ক্যারিয়ারকে বিমানবন্দরের একটি গোপন জেরা কক্ষে নিয়ে গিয়ে কাস্টমস অফিসাররা অত্যন্ত কঠোর জিজ্ঞাসাবাদ শুরু করে। চোরাই সোনা কোথায় ও কীভাবে লুকানো আছে তা জানতে চেয়ে অফিসাররা প্রচণ্ড চাপ সৃষ্টি করে। ক্যারিয়ারটি নিজেকে নির্দোষ প্রমাণ করার ব্যর্থ চেষ্টা করলেও অফিসাররা নিশ্চিত হয়ে যায় যে চালানের মূল রহস্য তার লাগেজেই লুকিয়ে আছে।"),
    ("investigation", "তদন্তকারী দল আটক ব্যক্তির কাছ থেকে উদ্ধার করে অতি সস্তা ও সাধারণ চাইনিজ ফিচার ফোন, যা আন্তর্জাতিক সিন্ডিকেট নিজেদের গোপন বার্তার জন্য ব্যবহার করে আসছিল। ডিজিটাল ট্র্যাকিং এড়াতে ব্যবহৃত এই বার্নার ফোনের সিম ও যোগাযোগের রেকর্ড ঘেঁটে অফিসাররা বুঝতে পারে এই চোরাচালানের পেছনে অতি চতুর কোনো মাস্টারমাইন্ড রয়েছে।"),
    ("investigation", "আমির ও তার বিশ্বস্ত দল তাদের পরবর্তী দুঃসাহসিক অপারেশনের প্রতিটি সূক্ষ্ম বিষয় চূড়ান্ত করে ফেলে। ২৭ তারিখ সকাল ৯টা ৪০ মিনিটে দুবাই থেকে কোয়েম্বাটুরে অবতরণকারী ফ্লাইটে এই ঝটিকা অভিযান সম্পন্ন করতে হবে। সেকেন্ডের নির্ভুল হিসাব ও ট্রানজিট পয়েন্টের প্রতিটি ঝুঁকি পর্যালোচনা করে তারা ময়দানে নামার জন্য সম্পূর্ণ প্রস্তুত হয়।"),
    ("investigation", "নির্দিষ্ট সময়ে বিমান রানওয়েতে অবতরণের পর টার্মিনালে শুরু হয় রোমাঞ্চকর ছদ্মবেশী মুভমেন্ট। আলী সালামত নামের মাধ্যমে পরিচালিত এই হাই-রিস্ক মিশনে কাস্টমস অফিসারদের তীক্ষ্ণ চোখকে ধুলো দিয়ে কোটি টাকার স্বর্ণের কনসাইনমেন্টটি অত্যন্ত ঠান্ডা মাথায় ও নির্ভুল কৌশলে টার্মিনাল থেকে নিরাপদে বাইরে বের করে নিয়ে আসা হয়।"),

    # Act 5: Escalation & Power Clash (25-34)
    ("escalation", "সিন্ডিকেটের শীর্ষ মাফিয়ারা মুখোমুখি দাঁড়িয়ে নিজেদের আধিপত্যের দাবি ও এলাকার হিসেব বুঝিয়ে দিতে চায়। এই শহরে কাজ করতে হলে সবাইকে তোলামি ও সিন্ডিকেটের প্রটেকশন মানতে হবে—এই নিয়ে অপরাধীদের অন্দরে শুরু হয় তুমুল বাগ্‌বিতণ্ডা ও শক্তির অহংকার। পুরো আন্ডারওয়ার্ল্ডে ছড়িয়ে পড়ে গভীর অবিশ্বাস, অসন্তোষ আর আসন্ন গৃহযুদ্ধের গন্ধ।"),
    ("escalation", "সেক্রেটারি রাঘবনের অনুগত গুণ্ডারা সাধারণ স্বর্ণ ক্যারিয়ারদের প্রকাশ্যে ভয়ভীতি দেখাতে শুরু করে। তারা কঠোর হুমকি দেয় যে তাদের আদেশ অমান্য করলে তাদের পাসপোর্ট ছিঁড়ে ফেলা হবে এবং ভুয়া মাদক বা চোরাই ট্রাকের মামলায় জড়িয়ে সারাজীবনের জন্য জেলে পচিয়ে দেওয়া হবে। সিন্ডিকেটের এই নির্লজ্জ ব্ল্যাকমেইল ও ক্ষমতার অপব্যবহার চরম আকার ধারণ করে।"),
    ("escalation", "তদন্তে এক চাঞ্চল্যকর ও মর্মান্তিক সত্য উন্মোচিত হয়—বেসরকারি এয়ারলাইন্স সংস্থাটি গভীর অর্থনৈতিক সংকটে নিমজ্জিত এবং বিগত ছয় মাস ধরে তাদের কোনো কেবিন ক্রুকে বেতন দেওয়া হয়নি। এই সুযোগেই চতুর সিন্ডিকেট অসহায় ও অভাবগ্রস্ত বিমানকর্মীদের বিপুল অঙ্কের অর্থের টোপ ফেলে আন্তর্জাতিক স্বর্ণের গোপন বাহক হিসেবে ব্যবহারের ফাঁদে ফেলে।"),
    ("escalation", "এক রুদ্ধশ্বাস গোপন বৈঠকে সরাসরি এক অবিশ্বাস্য প্রস্তাব উত্থাপন করা হয়—কারিপুর আন্তর্জাতিক বিমানবন্দরকে ব্যবহার করে প্রতিদিন ত্রিশ কেজি খাঁটি সোনা চোরাচালানের এক বিশাল নেটওয়ার্ক গড়ে তোলা। প্রতিদিন এত বিপুল পরিমাণ সোনা নামানোর এই দুঃসাহসিক ছক শুনে বৈঠকে উপস্থিত প্রত্যেকে এক মুহূর্তের জন্য বিস্ময়ে বাকরুদ্ধ হয়ে পড়ে।"),
    ("escalation", "ক্ষমতাসীন দলের প্রভাবশালী সেক্রেটারি পুন্নাভেল রাঘবনের সাথে অনুষ্ঠিত হয় এক অত্যন্ত স্পর্শকাতর গোপন বৈঠক। বাণিজ্যিক ব্র্যান্ড সম্প্রসারণের আড়ালে পুরো কেরালা জুড়ে সিন্ডিকেটের এই কোটি কোটি টাকার অবৈধ স্বর্ণ সাম্রাজ্যকে রাজনৈতিক ছত্রচ্ছায়ায় অবাধে ছড়িয়ে দেওয়ার বিষয়ে উভয় পক্ষের মধ্যে মোটা অঙ্কের গোপন চুক্তি সম্পন্ন হয়।"),
    ("escalation", "সেক্রেটারি রাঘবনের ব্যক্তিগত বাংলোর খাস কামরায় প্রবেশ করে তার কেনা এক দুর্নীতিগ্রস্ত শীর্ষ পুলিশ কর্মকর্তা। রাঘবন সাফ জানিয়ে দেয় যে তার রাজনৈতিক ভাবমূর্তি ও মর্যাদায় যেন বিন্দুমাত্র দাগ না লাগে। পুলিশ বাহিনীকে সরাসরি নির্দেশ দেওয়া হয় যেভাবেই হোক সমস্ত প্রমাণ ধামাচাপা দিয়ে সিন্ডিকেটের পথ নিষ্কণ্টক রাখতে হবে।"),
    ("escalation", "ফাঁস হয়ে যায় এক কুৎসিত ষড়যন্ত্র—হ্যারিস বশীর এবং সেক্রেটারি রাঘবন তাদের পথের কাঁটা দূর করতে এক পেশাদার গোয়ান হিটম্যানকে খুনের সুপারি দিয়েছিল। কিন্তু দুর্ভাগ্যবশত সেই ভাড়াটে শুটার নিজেই প্রাণ হারিয়েছে। একের পর এক হিসাব উল্টে যাওয়ায় সিন্ডিকেটের শীর্ষ মহলে তীব্র হতাশা ও অস্থিরতা ছড়িয়ে পড়ে।"),
    ("escalation", "ধৃত এক অপরাধী পুলিশের কঠিন জেরার মুখে ভেঙে পড়ে স্বীকার করে যে কালিকট গ্লোবালের আড়ালে উদ্ধার করা বিপুল সোনা আসলে খোদ সেক্রেটারি রাঘবনের প্রত্যক্ষ নির্দেশেই আনা হয়েছিল। এই চাক্ষুষ স্বীকারোক্তি রাঘবনের রাজনৈতিক মুখোশ পুরোপুরি টেনে ছিঁড়ে ফেলে এবং আমিরের হাতে তুলে দেয় সবচেয়ে বড় আইনি তুরুপের তাস।"),
    ("escalation", "আমির নিজের অবিশ্বাস্য রণকৌশল খাটিয়ে প্রতিপক্ষের নাকের ডগা দিয়ে পুরো কোটি টাকার সোনার চালান একাই নিজের জিম্মায় তুলে নেয়। ফোনে নিজের বিশ্বস্ত সাথীদের আমির অত্যন্ত শান্ত ও আত্মবিশ্বাসী গলায় জানিয়ে দেয় যে মাল সে তুলে নিয়েছে। প্রতিপক্ষের মাফিয়ারা শূন্যহাতে দাঁড়িয়ে চরম অপমান ও পরাজয়ের মুখোমুখি হয়।"),
